MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(loop:ProcessInstrumentationFunction {loop_tag: 'PI-15009'})
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-701'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (p:PlantItem {tag: 'P-1802'})-[:line_to*1..]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-1002A'}),
      (b:PlantItem {tag: 'TK-1101'}),
      (blocked:PlantItem {tag: 'CHV-10003'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x <> blocked AND y <> blocked)+ (b)
} AS reachable YYST	final

MATCH (a:PlantItem {tag: 'P-1002A'}),
      (b:PlantItem {tag: 'TK-1101'}),
      (blocked:PlantItem {tag: 'CHV-10003'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x <> blocked AND y <> blocked)+ (b)
} AS reachable

MATCH (e:PlantItem {tag: 'P-501'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (equipment:PlantItem {tag: 'E-701'})-[:line_to]-(valve:Valve)<-[:control]-(actuator:ActuatingFunction)<-[:send_signal_to*1..]-(loop:ProcessInstrumentationFunction)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-201'}), (b:PlantItem {tag: 'V-601'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*]->(b))
         WHERE NONE(n IN nodes(p) WHERE n.tag = 'YV-3009')
       } AS reachable

MATCH (loop:ProcessControlFunction {loop_tag: 'LIC-10054'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

